let url,
  daftar = $("#daftar").DataTable({
    responsive: !0,
    scrollX: !0,
    ajax: readUrl,
    columnDefs: [
      {
        searcable: !1,
        orderable: !1,
        targets: 0,
      },
    ],
    order: [[1, "asc"]],
    columns: [
      {
        data: "no",
      },
      {
        data: "email",
      },
      {
        data: "nama",
      },
      {
        data: "nohp",
      },
      {
        data: "alamat",
      },
      {
        data: "nama_siswa",
      },
      {
        data: "proses",
      },
      {
        data: null,
        title: "Action",
        render: function (data, type, row, meta) {
          return (
            '<button class="btn btn-sm btn-success" onclick="edit(' +
            data["no"] +
            ')">Status Proses</button>'
          );
        },
      },
    ],
  });

function reloadTable() {
  daftar.ajax.reload();
}

function editData() {
  $.ajax({
    url: editUrl,
    type: "post",
    dataType: "json",
    data: $("#form").serialize(),
    success: () => {
      $(".modal").modal("hide"),
        Swal.fire("Sukses", "Sukses Memproses Data", "success"),
        reloadTable();
    },
    error: (a) => {
      console.log(a);
    },
  });
}

function add() {
  (url = "add"),
    $(".modal-title").html("Add Data"),
    $('.modal button[type="submit"]').html("Add");
}

function edit(a) {
  $.ajax({
    url: getProdukUrl,
    type: "get",
    dataType: "json",
    data: {
      no: a,
    },
    success: (a) => {
      $('[name="no"]').val(a.no),
        $('[name="proses"]').val(a.proses),
        $(".modal").modal("show"),
        $(".modal-title").html("Proses"),
        $('.modal button[type="submit"]').html("Edit"),
        (url = "edit");
    },
    error: (a) => {
      console.log(a);
    },
  });
}
daftar.on("order.dt search.dt", () => {
  daftar
    .column(0, {
      search: "applied",
      order: "applied",
    })
    .nodes()
    .each((a, e) => {
      a.innerHTML = e + 1;
    });
}),
  $("#form").validate({
    errorElement: "span",
    errorPlacement: (a, e) => {
      a.addClass("invalid-feedback"), e.closest(".form-group").append(a);
    },
    submitHandler: () => {
      "edit" == url ? editData() : addData();
    },
  }),
  $("#kategori").select2({
    placeholder: "Kategori",
    ajax: {
      url: kategoriSearchUrl,
      type: "post",
      dataType: "json",
      data: (a) => ({
        kategori: a.term,
      }),
      processResults: (a) => ({
        results: a,
      }),
      cache: !0,
    },
  }),
  $("#satuan").select2({
    placeholder: "Satuan",
    ajax: {
      url: satuanSearchUrl,
      type: "post",
      dataType: "json",
      data: (a) => ({
        satuan: a.term,
      }),
      processResults: (a) => ({
        results: a,
      }),
      cache: !0,
    },
  }),
  $(".modal").on("hidden.bs.modal", () => {
    $("#form")[0].reset(), $("#form").validate().resetForm();
  });
